{"items":[{"id":"cap-v2-ordering_and_selection-go-generation-01","problem":"Implement a submission-ranking API in Go.

Use package `solution` and provide this public API:

```go
type Submission struct {
    SubmissionID  string
    Title         string
    JuryPoints    int
    AudiencePoints int
}

func RankSubmissions(input []Submission) []Submission
```

Multiple input values may have the same `SubmissionID`. Emit exactly one submission per ID. For each duplicated ID, select the submission with the greatest `JuryPoints`; if tied, select the one with the greatest `AudiencePoints`; if still tied, select the lexicographically smaller `Title`. Candidates still tied after these comparisons are identical for all relevant fields.

Rank the selected submissions by descending `JuryPoints`, then descending `AudiencePoints`, then ascending `Title`, then ascending `SubmissionID`. Return an empty non-nil slice for empty input.

The implementation must be deterministic and use only the Go standard library. Do not perform filesystem, network, clock, or random operations. Return a complete source file without a `main` function.","reference_code":"package solution

import "sort"

type Submission struct {
	SubmissionID   string
	Title          string
	JuryPoints     int
	AudiencePoints int
}

func RankSubmissions(input []Submission) []Submission {
	best := make(map[string]Submission, len(input))
	for _, candidate := range input {
		current, exists := best[candidate.SubmissionID]
		if !exists || preferredSubmission(candidate, current) {
			best[candidate.SubmissionID] = candidate
		}
	}

	result := make([]Submission, 0, len(best))
	for _, submission := range best {
		result = append(result, submission)
	}

	sort.Slice(result, func(i, j int) bool {
		a, b := result[i], result[j]
		if a.JuryPoints != b.JuryPoints {
			return a.JuryPoints > b.JuryPoints
		}
		if a.AudiencePoints != b.AudiencePoints {
			return a.AudiencePoints > b.AudiencePoints
		}
		if a.Title != b.Title {
			return a.Title < b.Title
		}
		return a.SubmissionID < b.SubmissionID
	})

	return result
}

func preferredSubmission(a, b Submission) bool {
	if a.JuryPoints != b.JuryPoints {
		return a.JuryPoints > b.JuryPoints
	}
	if a.AudiencePoints != b.AudiencePoints {
		return a.AudiencePoints > b.AudiencePoints
	}
	return a.Title < b.Title
}
