func TestRankSubmissionsSelectionAndOrdering(t *testing.T) {
	input := []Submission{
		{SubmissionID: "jury", Title: "Old", JuryPoints: 8, AudiencePoints: 100},
		{SubmissionID: "jury", Title: "Winner", JuryPoints: 9, AudiencePoints: 0},
		{SubmissionID: "audience", Title: "Old", JuryPoints: 7, AudiencePoints: 4},
		{SubmissionID: "audience", Title: "Winner", JuryPoints: 7, AudiencePoints: 5},
		{SubmissionID: "title", Title: "Zulu", JuryPoints: 6, AudiencePoints: 3},
		{SubmissionID: "title", Title: "Alpha", JuryPoints: 6, AudiencePoints: 3},
		{SubmissionID: "b", Title: "Same", JuryPoints: 5, AudiencePoints: 2},
		{SubmissionID: "a", Title: "Same", JuryPoints: 5, AudiencePoints: 2},
		{SubmissionID: "low", Title: "First", JuryPoints: -1, AudiencePoints: 100},
	}
	original := append([]Submission(nil), input...)

	got := RankSubmissions(input)
	want := []Submission{
		{SubmissionID: "jury", Title: "Winner", JuryPoints: 9, AudiencePoints: 0},
		{SubmissionID: "audience", Title: "Winner", JuryPoints: 7, AudiencePoints: 5},
		{SubmissionID: "title", Title: "Alpha", JuryPoints: 6, AudiencePoints: 3},
		{SubmissionID: "a", Title: "Same", JuryPoints: 5, AudiencePoints: 2},
		{SubmissionID: "b", Title: "Same", JuryPoints: 5, AudiencePoints: 2},
		{SubmissionID: "low", Title: "First", JuryPoints: -1, AudiencePoints: 100},
	}

	if !reflect.DeepEqual(got, want) {
		t.Fatalf("RankSubmissions() = %#v, want %#v", got, want)
	}
	if !reflect.DeepEqual(input, original) {
		t.Fatalf("RankSubmissions mutated input: got %#v, want %#v", input, original)
	}
}

func TestRankSubmissionsOrderingPrecedence(t *testing.T) {
	input := []Submission{
		{SubmissionID: "d", Title: "Alpha", JuryPoints: 10, AudiencePoints: 1},
		{SubmissionID: "c", Title: "Zulu", JuryPoints: 10, AudiencePoints: 2},
		{SubmissionID: "b", Title: "Beta", JuryPoints: 10, AudiencePoints: 2},
		{SubmissionID: "a", Title: "Beta", JuryPoints: 10, AudiencePoints: 2},
	}
	want := []Submission{input[3], input[2], input[1], input[0]}

	if got := RankSubmissions(input); !reflect.DeepEqual(got, want) {
		t.Fatalf("RankSubmissions() = %#v, want %#v", got, want)
	}
}

func TestRankSubmissionsEmptyIsNonNil(t *testing.T) {
	for _, input := range [][]Submission{nil, {}} {
		got := RankSubmissions(input)
		if got == nil {
			t.Fatal("RankSubmissions returned nil for empty input")
		}
		if len(got) != 0 {
			t.Fatalf("RankSubmissions returned %d elements for empty input", len(got))
		}
	}
}
