			{URL: "https://title", Title: "Zulu", Source: "a", Confidence: 6},
		},
		{
			{URL: "https://title", Title: "Alpha", Source: "a", Confidence: 6},
			{URL: "https://a", Title: "Same", Source: "s", Confidence: 7},
		},
	}
	original := make([][]SearchResult, len(batches))
	for i := range batches {
		original[i] = append([]SearchResult(nil), batches[i]...)
	}

	got := MergeSearchResults(batches)
	want := []SearchResult{
		{URL: "https://jury", Title: "Winner", Source: "z", Confidence: 11},
		{URL: "https://source", Title: "Zulu", Source: "a", Confidence: 8},
		{URL: "https://a", Title: "Same", Source: "s", Confidence: 7},
		{URL: "https://b", Title: "Same", Source: "s", Confidence: 7},
		{URL: "https://title", Title: "Alpha", Source: "a", Confidence: 6},
	}

	if !reflect.DeepEqual(got, want) {
		t.Fatalf("MergeSearchResults() = %#v, want %#v", got, want)
	}
	if !reflect.DeepEqual(batches, original) {
		t.Fatalf("MergeSearchResults mutated input: got %#v, want %#v", batches, original)
	}
}

func TestMergeSearchResultsOrderingPrecedence(t *testing.T) {
	input := [][]SearchResult{{
		{URL: "u4", Title: "Alpha", Source: "b", Confidence: 4},
		{URL: "u3", Title: "Zulu", Source: "a", Confidence: 5},
		{URL: "u2", Title: "Beta", Source: "z", Confidence: 5},
		{URL: "u1", Title: "Beta", Source: "a", Confidence: 5},
