import (
	"reflect"
	"testing"
)

func cloneChapters(input []Chapter) []Chapter {
	out := make([]Chapter, len(input))
	for i, chapter := range input {
		out[i] = chapter
		if chapter.Keywords != nil {
			out[i].Keywords = append([]string(nil), chapter.Keywords...)
		}
	}
	return out
}

func TestOrderChaptersOrderingStabilityAndDeepIndependence(t *testing.T) {
	input := []Chapter{
		{Code: "stable", Section: 2, Importance: 7, Keywords: []string{"first", "shared"}},
		{Code: "later", Section: 3, Importance: 100, Keywords: nil},
		{Code: "stable", Section: 2, Importance: 7, Keywords: []string{"second"}},
		{Code: "important", Section: 2, Importance: 9, Keywords: []string{}},
		{Code: "alpha", Section: 2, Importance: 7, Keywords: []string{"alpha"}},
		{Code: "early", Section: 1, Importance: 0, Keywords: []string{"early"}},
	}
	original := cloneChapters(input)
	want := []Chapter{input[5], input[3], input[4], input[0], input[2], input[1]}

	got := OrderChapters(input)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("OrderChapters() = %#v, want %#v", got, want)
	}
	if !reflect.DeepEqual(input, original) {
		t.Fatalf("OrderChapters mutated input: got %#v, want %#v", input, original)
	}

	got[3].Code = "changed"
	got[3].Keywords[0] = "changed"
	if !reflect.DeepEqual(input, original) {
		t.Fatalf("changing result changed input: got %#v, want %#v", input, original)
	}
}

func TestOrderChaptersPreservesNilAndEmptyKeywords(t *testing.T) {
	input := []Chapter{
		{Code: "nil", Keywords: nil},
		{Code: "empty", Keywords: []string{}},
	}
	got := OrderChapters(input)

	var nilChapter, emptyChapter *Chapter
	for i := range got {
		switch got[i].Code {
		case "nil":
			nilChapter = &got[i]
		case "empty":
			emptyChapter = &got[i]
		}
	}
	if nilChapter == nil || nilChapter.Keywords != nil {
		t.Fatalf("nil Keywords was not preserved: %#v", nilChapter)
	}
	if emptyChapter == nil || emptyChapter.Keywords == nil || len(emptyChapter.Keywords) != 0 {
		t.Fatalf("non-nil empty Keywords was not preserved: %#v", emptyChapter)
	}
}

func TestOrderChaptersEmptyIsNonNil(t *testing.T) {
	for _, input := range [][]Chapter{nil, {}} {
		got := OrderChapters(input)
		if got == nil {
			t.Fatal("OrderChapters returned nil for empty input")
		}
		if len(got) != 0 {
			t.Fatalf("OrderChapters returned %d chapters, want zero", len(got))
		}
	}
}
