The exact public API is:

```go
type CatalogEntry struct {
    Code  string
    Price uint64
}

type Catalog struct {
    Unit    string
    Entries []CatalogEntry
}

func DecodeCatalog(text string) (Catalog, error)
```

The input uses LF-separated lines. The first line must be `unit=XXX`, where `XXX` is exactly three ASCII uppercase letters. It must be followed by at least one entry line. Each entry line has the form `CODE,PRICE`.

`CODE` must be non-empty and contain only ASCII uppercase letters, digits, or hyphens. Codes must be unique. `PRICE` must be a non-empty sequence of ASCII decimal digits representing a value that fits in `uint64`. Whitespace is not ignored or trimmed.

Return a non-nil error for every format violation, including missing fields, extra separators, invalid characters, duplicate codes, empty lines, and a trailing newline. On error, the returned catalog may be the zero value. Preserve entries in their encoded sequence.

Return one complete Go source file using package `solution`. Use only the standard library. Do not access the filesystem, network, clock, or randomness.","reference_code":"package solution

import (
	"fmt"
	"strconv"
	"strings"
)

type CatalogEntry struct {
	Code  string
	Price uint64
}

type Catalog struct {
	Unit    string
	Entries []CatalogEntry
}

func DecodeCatalog(text string) (Catalog, error) {
	lines := strings.Split(text, "\n")
	if len(lines) < 2 {
		return Catalog{}, fmt.Errorf("catalog requires a header and an entry")
	}
	if len(lines[0]) != 8 || !strings.HasPrefix(lines[0], "unit=") {
		return Catalog{}, fmt.Errorf("invalid unit header")
	}
	unit := lines[0][5:]
	for i := 0; i < len(unit); i++ {
		if unit[i] < 'A' || unit[i] > 'Z' {
			return Catalog{}, fmt.Errorf("invalid unit")
		}
	}

	entries := make([]CatalogEntry, 0, len(lines)-1)
	seen := make(map[string]struct{}, len(lines)-1)
	for _, line := range lines[1:] {
		if line == "" {
			return Catalog{}, fmt.Errorf("empty entry line")
		}
		if strings.Count(line, ",") != 1 {
			return Catalog{}, fmt.Errorf("invalid entry")
		}
		parts := strings.SplitN(line, ",", 2)
		code, encodedPrice := parts[0], parts[1]
		if code == "" || !validCatalogCode(code) {
			return Catalog{}, fmt.Errorf("invalid code")
		}
		if _, exists := seen[code]; exists {
			return Catalog{}, fmt.Errorf("duplicate code")
		}
		if encodedPrice == "" || !asciiDigits(encodedPrice) {
			return Catalog{}, fmt.Errorf("invalid price")
		}
		price, err := strconv.ParseUint(encodedPrice, 10, 64)
		if err != nil {
			return Catalog{}, fmt.Errorf("invalid price: %w", err)
		}
		seen[code] = struct{}{}
		entries = append(entries, CatalogEntry{Code: code, Price: price})
	}

	return Catalog{Unit: unit, Entries: entries}, nil
}

func validCatalogCode(code string) bool {
	for i := 0; i < len(code); i++ {
		c := code[i]
		if (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != '-' {
			return false
		}
	}
	return true
}

func asciiDigits(value string) bool {
	for i := 0; i < len(value); i++ {
		if value[i] < '0' || value[i] > '9' {
			return false
		}
	}
	return true
}
