The public API parses a pipe-separated binding list:

```go
type Binding struct {
    Name  string
    Value string
}

func ParseBindings(text string) ([]Binding, error)
```

The input must contain one or more fields of the form `name:value`. Names must be non-empty ASCII lowercase letters, values must be non-empty ASCII decimal digits, and names must not repeat. Whitespace is significant and therefore invalid in either component. Empty fields and extra or missing colons are invalid.

The returned bindings must remain in exactly the same order in which their fields occur in the text. Return a non-nil error for invalid input.

Use package `solution` and only the standard library. Do not access the filesystem, network, clock, or randomness.

```go
package solution

import (
	"fmt"
	"sort"
	"strings"
)

type Binding struct {
	Name  string
	Value string
}

func ParseBindings(text string) ([]Binding, error) {
	if text == "" {
		return nil, fmt.Errorf("empty binding list")
	}

	fields := strings.Split(text, "|")
	result := make([]Binding, 0, len(fields))
	seen := make(map[string]struct{}, len(fields))
	for _, field := range fields {
		if strings.Count(field, ":") != 1 {
			return nil, fmt.Errorf("invalid field")
		}
		parts := strings.SplitN(field, ":", 2)
		name, value := parts[0], parts[1]
		if !lowercaseName(name) || !decimalValue(value) {
			return nil, fmt.Errorf("invalid binding")
		}
		if _, exists := seen[name]; exists {
			return nil, fmt.Errorf("duplicate name")
		}
		seen[name] = struct{}{}
		result = append(result, Binding{Name: name, Value: value})
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i].Name < result[j].Name
	})
	return result, nil
}

func lowercaseName(value string) bool {
	if value == "" {
		return false
	}
	for i := 0; i < len(value); i++ {
		if value[i] < 'a' || value[i] > 'z' {
			return false
		}
	}
	return true
}

func decimalValue(value string) bool {
	if value == "" {
		return false
	}
	for i := 0; i < len(value); i++ {
		if value[i] < '0' || value[i] > '9' {
			return false
		}
	}
	return true
}
