func TestDecodeCatalogValid(t *testing.T) {
	tests := []struct {
		name string
		text string
		want Catalog
	}{
		{
			name: "single entry",
			text: "unit=USD\nITEM-1,250",
			want: Catalog{Unit: "USD", Entries: []CatalogEntry{{Code: "ITEM-1", Price: 250}}},
		},
		{
			name: "preserves entry order",
			text: "unit=EUR\nZ9,7\nA-2,19\nM,0",
			want: Catalog{Unit: "EUR", Entries: []CatalogEntry{
				{Code: "Z9", Price: 7},
				{Code: "A-2", Price: 19},
				{Code: "M", Price: 0},
			}},
		},
		{
			name: "maximum price",
			text: "unit=JPY\nMAX,18446744073709551615",
			want: Catalog{Unit: "JPY", Entries: []CatalogEntry{{Code: "MAX", Price: ^uint64(0)}}},
		},
		{
			name: "leading zeroes and minimal valid code",
			text: "unit=GBP\n-,00001\n9,00",
			want: Catalog{Unit: "GBP", Entries: []CatalogEntry{
				{Code: "-", Price: 1},
				{Code: "9", Price: 0},
			}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := DecodeCatalog(tt.text)
			if err != nil {
				t.Fatalf("DecodeCatalog returned error: %v", err)
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("DecodeCatalog() = %#v, want %#v", got, tt.want)
