		{
			name: "long decimal value",
			text: "amount:999999999999999999999999999999999999",
			want: []Binding{{Name: "amount", Value: "999999999999999999999999999999999999"}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParseBindings(tt.text)
			if err != nil {
				t.Fatalf("ParseBindings returned error: %v", err)
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("ParseBindings() = %#v, want %#v", got, tt.want)
			}
		})
	}
}

func TestParseBindingsRejectsMalformedInput(t *testing.T) {
	tests := []struct {
		name string
		text string
	}{
		{"empty input", ""},
		{"empty field at start", "|a:1"},
		{"empty field at end", "a:1|"},
		{"empty field in middle", "a:1||b:2"},
		{"missing colon", "alpha1"},
		{"extra colon", "alpha:1:2"},
		{"empty name", ":1"},
		{"empty value", "alpha:"},
		{"uppercase name", "Alpha:1"},
		{"digit in name", "alpha1:2"},
		{"hyphen in name", "alpha-beta:2"},
		{"non ASCII name", "café:1"},
		{"space in name", "alpha beta:1"},
		{"space in value", "alpha:1 2"},
		{"negative value", "alpha:-1"},
		{"positive sign", "alpha:+1"},
		{"decimal point", "alpha:1.5"},
		{"non ASCII digit", "alpha:١"},
		{"duplicate adjacent name", "alpha:1|alpha:2"},
		{"duplicate separated name", "alpha:1|beta:2|alpha:3"},
		{"newline", "alpha:1\nbeta:2"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := ParseBindings(tt.text); err == nil {
				t.Fatalf("ParseBindings(%q) returned nil error", tt.text)
			}
		})
	}
}

func TestParseBindingsRepeatedCallsRemainStable(t *testing.T) {
	first, err := ParseBindings("zeta:1|alpha:2")
	if err != nil {
		t.Fatalf("first call returned error: %v", err)
	}
	second, err := ParseBindings("beta:3")
	if err != nil {
		t.Fatalf("second call returned error: %v", err)
	}

	wantFirst := []Binding{{Name: "zeta", Value: "1"}, {Name: "alpha", Value: "2"}}
	wantSecond := []Binding{{Name: "beta", Value: "3"}}
	if !reflect.DeepEqual(first, wantFirst) {
		t.Fatalf("first result changed or was reordered: %#v", first)
	}
	if !reflect.DeepEqual(second, wantSecond) {
		t.Fatalf("second result = %#v, want %#v", second, wantSecond)
	}
}
