func TestDecodeTrailValidAndOrdered(t *testing.T) {
	tests := []struct {
		name    string
		encoded string
		want    []string
	}{
		{
			name:    "single segment",
			encoded: "/north",
			want:    []string{"north"},
		},
		{
			name:    "example preserves order",
			encoded: "/north/green%20room/final",
			want:    []string{"north", "green room", "final"},
		},
		{
			name:    "plus is literal in path decoding",
			encoded: "/a+b/%7Euser",
			want:    []string{"a+b", "~user"},
		},
		{
			name:    "encoded percent does not decode twice",
			encoded: "/%252F/end",
			want:    []string{"%2F", "end"},
		},
		{
			name:    "nul byte is a nonempty segment",
			encoded: "/%00/x",
			want:    []string{"\x00", "x"},
		},
		{
			name:    "literal punctuation",
			encoded: "/what?query/fragment#mark",
			want:    []string{"what?query", "fragment#mark"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := DecodeTrail(tt.encoded)
			if err != nil {
				t.Fatalf("DecodeTrail returned error: %v", err)
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("DecodeTrail() = %#v, want %#v", got, tt.want)
			}
		})
	}
}

func TestDecodeTrailRejectsMalformedInput(t *testing.T) {
	tests := []struct {
		name    string
		encoded string
	}{
		{"empty input", ""},
		{"no leading slash", "north/south"},
		{"only slash", "/"},
		{"leading empty segment", "//north"},
		{"middle empty segment", "/north//south"},
		{"trailing empty segment", "/north/"},
		{"bare percent", "/north/%"},
		{"short escape", "/north/%2"},
		{"non hexadecimal escape", "/north/%GG"},
		{"uppercase encoded slash", "/north%2Fsouth"},
		{"lowercase encoded slash", "/north%2fsouth"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := DecodeTrail(tt.encoded); err == nil {
				t.Fatalf("DecodeTrail(%q) returned nil error", tt.encoded)
			}
		})
	}
}

func TestDecodeTrailRepeatedCallsPreservePriorOrder(t *testing.T) {
	first, err := DecodeTrail("/z/a/m")
	if err != nil {
		t.Fatalf("first call returned error: %v", err)
	}
	if _, err := DecodeTrail("/other"); err != nil {
		t.Fatalf("second call returned error: %v", err)
	}
	want := []string{"z", "a", "m"}
	if !reflect.DeepEqual(first, want) {
		t.Fatalf("first result = %#v, want %#v", first, want)
	}
}
