func TestDeltaEncode(t *testing.T) {
	tests := []struct {
		name   string
		values []int
		want   []int
	}{
		{"single value", []int{7}, []int{7}},
		{"increasing", []int{3, 8, 10, 21}, []int{3, 5, 2, 11}},
		{"decreasing", []int{10, 7, 1, -2}, []int{10, -3, -6, -3}},
		{"mixed and repeated", []int{-5, -5, 0, -4, 6}, []int{-5, 0, 5, -4, 10}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			original := append([]int(nil), tt.values...)
			got := DeltaEncode(tt.values)
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("DeltaEncode() = %#v, want %#v", got, tt.want)
			}
			if !reflect.DeepEqual(tt.values, original) {
				t.Fatalf("input was modified: got %#v, want %#v", tt.values, original)
			}
		})
	}
}

func TestDeltaEncodeEmpty(t *testing.T) {
	if got := DeltaEncode(nil); len(got) != 0 {
		t.Fatalf("DeltaEncode(nil) length = %d, want 0", len(got))
	}
	if got := DeltaEncode([]int{}); len(got) != 0 {
		t.Fatalf("DeltaEncode(empty) length = %d, want 0", len(got))
	}
}

func TestDeltaEncodeDoesNotAliasInput(t *testing.T) {
	input := []int{4, 9, 15}
	got := DeltaEncode(input)

	got[0] = 999
	if !reflect.DeepEqual(input, []int{4, 9, 15}) {
		t.Fatalf("mutating result changed input: %#v", input)
	}

	input[1] = -100
	if !reflect.DeepEqual(got, []int{999, 5, 6}) {
		t.Fatalf("mutating input changed result: %#v", got)
	}
}

func TestDeltaEncodeCallsAreStateIsolated(t *testing.T) {
	first := DeltaEncode([]int{1, 4, 9})
	firstSnapshot := append([]int(nil), first...)

	second := DeltaEncode([]int{100, 80, 70})
	if !reflect.DeepEqual(first, firstSnapshot) {
		t.Fatalf("later call changed first result: got %#v, want %#v", first, firstSnapshot)
	}

	second[0] = -1
	if !reflect.DeepEqual(first, firstSnapshot) {
		t.Fatalf("mutating second result changed first result: got %#v, want %#v", first, firstSnapshot)
	}

	first[1] = 777
	if !reflect.DeepEqual(second, []int{-1, -20, -10}) {
		t.Fatalf("mutating first result changed second result: %#v", second)
	}
}
