import (
	"reflect"
	"testing"
)

func TestRotateRows(t *testing.T) {
	tests := []struct {
		name  string
		rows  [][]int
		shift int
		want  [][]int
	}{
		{
			name:  "left rotation preserves row order",
			rows:  [][]int{{1, 2, 3, 4}, {9, 8, 7}, {5}},
			shift: 1,
			want:  [][]int{{2, 3, 4, 1}, {8, 7, 9}, {5}},
		},
		{
			name:  "negative shift rotates right",
			rows:  [][]int{{1, 2, 3, 4}, {10, 20, 30}},
			shift: -1,
			want:  [][]int{{4, 1, 2, 3}, {30, 10, 20}},
		},
		{
			name:  "large positive shift is normalized per row",
			rows:  [][]int{{1, 2, 3}, {4, 5, 6, 7, 8}},
			shift: 8,
			want:  [][]int{{3, 1, 2}, {7, 8, 4, 5, 6}},
		},
		{
			name:  "large negative shift is normalized per row",
			rows:  [][]int{{1, 2, 3}, {4, 5, 6, 7}},
			shift: -8,
			want:  [][]int{{2, 3, 1}, {4, 5, 6, 7}},
		},
		{
			name:  "zero shift copies rows unchanged",
			rows:  [][]int{{3, 2, 1}, {}, {7}},
			shift: 0,
			want:  [][]int{{3, 2, 1}, {}, {7}},
		},
		{
			name:  "empty rows remain empty",
			rows:  [][]int{nil, {}, {1, 2}},
			shift: 3,
			want:  [][]int{nil, {}, {2, 1}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			original := cloneRows(tt.rows)
			got := RotateRows(tt.rows, tt.shift)
			if len(got) != len(tt.want) {
				t.Fatalf("result row count = %d, want %d", len(got), len(tt.want))
			}
			for i := range tt.want {
				if !reflect.DeepEqual(got[i], tt.want[i]) && !(len(got[i]) == 0 && len(tt.want[i]) == 0) {
					t.Fatalf("row %d = %#v, want %#v", i, got[i], tt.want[i])
				}
			}
			if !rowsEqualByValues(tt.rows, original) {
				t.Fatalf("input was modified: got %#v, want %#v", tt.rows, original)
			}
		})
	}
}

func TestRotateRowsEmptyInputReturnsAllocatedOuterSlice(t *testing.T) {
	got := RotateRows(nil, 5)
	if got == nil {
		t.Fatal("RotateRows(nil, 5) returned nil; want a newly allocated empty outer slice")
	}
	if len(got) != 0 {
		t.Fatalf("result length = %d, want 0", len(got))
	}
}

func TestRotateRowsDoesNotAliasInput(t *testing.T) {
	input := [][]int{{1, 2, 3}, {4, 5}}
	got := RotateRows(input, 1)

	got[0][0] = 99
	got[1] = []int{100}
	if !reflect.DeepEqual(input, [][]int{{1, 2, 3}, {4, 5}}) {
		t.Fatalf("mutating result changed input: %#v", input)
	}

	input[0][1] = -20
	input[1] = []int{7, 8, 9}
	if !reflect.DeepEqual(got, [][]int{{99, 3, 1}, {100}}) {
		t.Fatalf("mutating input changed result: %#v", got)
	}
}

func TestRotateRowsAllocatesEachNonEmptyResultRowIndependently(t *testing.T) {
	shared := []int{1, 2, 3}
	input := [][]int{shared, shared}
	got := RotateRows(input, 1)

	got[0][0] = 999
	if !reflect.DeepEqual(got[1], []int{2, 3, 1}) {
		t.Fatalf("result rows share storage: second row is %#v", got[1])
	}
	if !reflect.DeepEqual(shared, []int{1, 2, 3}) {
		t.Fatalf("result row aliases input storage: input is %#v", shared)
	}
}

func TestRotateRowsCallsAreStateIsolated(t *testing.T) {
	first := RotateRows([][]int{{1, 2, 3}}, 1)
	second := RotateRows([][]int{{7, 8, 9}}, 2)
	second[0][0] = 42

	if !reflect.DeepEqual(first, [][]int{{2, 3, 1}}) {
		t.Fatalf("later call or mutation changed first result: %#v", first)
	}
}

func cloneRows(rows [][]int) [][]int {
	if rows == nil {
		return nil
	}
	copyRows := make([][]int, len(rows))
	for i := range rows {
		if rows[i] != nil {
			copyRows[i] = append([]int(nil), rows[i]...)
		}
	}
	return copyRows
}

func rowsEqualByValues(a, b [][]int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if len(a[i]) != len(b[i]) {
			return false
		}
		for j := range a[i] {
			if a[i][j] != b[i][j] {
				return false
			}
		}
	}
	return true
}
