		t.Fatalf("later call or mutation changed first result: %#v", first)
	}
}

func cloneRows(rows [][]int) [][]int {
	if rows == nil {
		return nil
	}
	copyRows := make([][]int, len(rows))
	for i := range rows {
		if rows[i] != nil {
			copyRows[i] = append([]int(nil), rows[i]...)
		}
	}
	return copyRows
}

func rowsEqualByValues(a, b [][]int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if len(a[i]) != len(b[i]) {
			return false
		}
		for j := range a[i] {
			if a[i][j] != b[i][j] {
				return false
			}
		}
	}
	return true
}
